-- Safe connection migration for دليل الضمير التعليمي.
-- Run after schema.sql. Adds public read policies and tightly scoped request RPCs.
-- No table grants let anonymous users read requests, access credential hashes, or approve records.

BEGIN;

ALTER TABLE public.teacher_requests
  ADD COLUMN IF NOT EXISTS control_code_hash text;

-- Initial reference data. IDs are generated by PostgreSQL; names are stable keys.
INSERT INTO public.subjects(name, sort_order) VALUES
 ('اللغة العربية',1),('اللغة الإنكليزية',2),('الرياضيات',3),('العلوم',4),
 ('الفيزياء',5),('الكيمياء',6),('الأحياء',7),('التاريخ',8),('الجغرافيا',9),('الحاسوب',10)
ON CONFLICT(name) DO NOTHING;
INSERT INTO public.education_stages(name, sort_order) VALUES
 ('المرحلة الابتدائية',1),('المرحلة الإعدادية',2),('المرحلة الثانوية',3)
ON CONFLICT(name) DO NOTHING;
INSERT INTO public.grades(stage_id,name,sort_order)
SELECT s.id,g.name,g.sort_order
FROM (VALUES
 ('المرحلة الابتدائية','الأول',1),('المرحلة الابتدائية','الثاني',2),('المرحلة الابتدائية','الثالث',3),
 ('المرحلة الابتدائية','الرابع',4),('المرحلة الابتدائية','الخامس',5),('المرحلة الابتدائية','السادس',6),
 ('المرحلة الإعدادية','السابع',1),('المرحلة الإعدادية','الثامن',2),('المرحلة الإعدادية','التاسع',3),
 ('المرحلة الثانوية','الأول الثانوي',1),('المرحلة الثانوية','الثاني الثانوي',2),('المرحلة الثانوية','الثالث الثانوي',3)
) AS g(stage_name,name,sort_order)
JOIN public.education_stages s ON s.name=g.stage_name
ON CONFLICT(stage_id,name) DO NOTHING;

-- Public read access only for published/active content.
GRANT SELECT ON public.schools, public.subjects, public.education_stages, public.grades,
  public.teachers, public.teacher_contacts, public.teacher_subjects,
  public.teacher_grade_assignments, public.teacher_schools, public.teacher_services,
  public.teacher_listings, public.teacher_listing_subjects, public.memorial_teachers, public.homepage_slides TO anon, authenticated;

DROP POLICY IF EXISTS public_active_schools_read ON public.schools;
DROP POLICY IF EXISTS public_subjects_read ON public.subjects;
DROP POLICY IF EXISTS public_stages_read ON public.education_stages;
DROP POLICY IF EXISTS public_grades_read ON public.grades;
DROP POLICY IF EXISTS public_published_teachers_read ON public.teachers;
DROP POLICY IF EXISTS public_teacher_contacts_read ON public.teacher_contacts;
DROP POLICY IF EXISTS public_teacher_subjects_read ON public.teacher_subjects;
DROP POLICY IF EXISTS public_teacher_grades_read ON public.teacher_grade_assignments;
DROP POLICY IF EXISTS public_teacher_schools_read ON public.teacher_schools;
DROP POLICY IF EXISTS public_teacher_services_read ON public.teacher_services;
DROP POLICY IF EXISTS public_listings_read ON public.teacher_listings;
DROP POLICY IF EXISTS public_listing_subjects_read ON public.teacher_listing_subjects;
DROP POLICY IF EXISTS public_memorials_read ON public.memorial_teachers;
DROP POLICY IF EXISTS public_slides_read ON public.homepage_slides;
CREATE POLICY public_active_schools_read ON public.schools FOR SELECT TO anon, authenticated USING (is_active);
CREATE POLICY public_subjects_read ON public.subjects FOR SELECT TO anon, authenticated USING (is_active);
CREATE POLICY public_stages_read ON public.education_stages FOR SELECT TO anon, authenticated USING (is_active);
CREATE POLICY public_grades_read ON public.grades FOR SELECT TO anon, authenticated USING (is_active);
CREATE POLICY public_published_teachers_read ON public.teachers FOR SELECT TO anon, authenticated USING (is_published);
CREATE POLICY public_teacher_contacts_read ON public.teacher_contacts FOR SELECT TO anon, authenticated USING (
  EXISTS (SELECT 1 FROM public.teachers t WHERE t.id=teacher_id AND t.is_published)
);
CREATE POLICY public_teacher_subjects_read ON public.teacher_subjects FOR SELECT TO anon, authenticated USING (
  EXISTS (SELECT 1 FROM public.teachers t WHERE t.id=teacher_id AND t.is_published)
);
CREATE POLICY public_teacher_grades_read ON public.teacher_grade_assignments FOR SELECT TO anon, authenticated USING (
  EXISTS (SELECT 1 FROM public.teachers t WHERE t.id=teacher_id AND t.is_published)
);
CREATE POLICY public_teacher_schools_read ON public.teacher_schools FOR SELECT TO anon, authenticated USING (
  EXISTS (SELECT 1 FROM public.teachers t WHERE t.id=teacher_id AND t.is_published)
);
CREATE POLICY public_teacher_services_read ON public.teacher_services FOR SELECT TO anon, authenticated USING (
  EXISTS (SELECT 1 FROM public.teachers t WHERE t.id=teacher_id AND t.is_published)
);
CREATE POLICY public_listings_read ON public.teacher_listings FOR SELECT TO anon, authenticated USING (
  status='published' AND EXISTS (SELECT 1 FROM public.teachers t WHERE t.id=teacher_id AND t.is_published)
);
CREATE POLICY public_listing_subjects_read ON public.teacher_listing_subjects FOR SELECT TO anon, authenticated USING (
  EXISTS (SELECT 1 FROM public.teacher_listings l JOIN public.teachers t ON t.id=l.teacher_id WHERE l.id=listing_id AND l.status='published' AND t.is_published)
);
CREATE POLICY public_memorials_read ON public.memorial_teachers FOR SELECT TO anon, authenticated USING (is_published);
CREATE POLICY public_slides_read ON public.homepage_slides FOR SELECT TO anon, authenticated USING (is_active);

-- Requests can only be inserted through these functions. Stored control codes are bcrypt hashes.
CREATE OR REPLACE FUNCTION public.submit_teacher_application(
  p_requested_name text, p_payload jsonb, p_control_code text
) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE request_id bigint;
BEGIN
  IF length(trim(coalesce(p_requested_name,''))) NOT BETWEEN 2 AND 200 THEN
    RAISE EXCEPTION 'اسم المعلم غير صالح';
  END IF;
  IF p_control_code !~ '^[0-9]{8}$' THEN
    RAISE EXCEPTION 'رمز التحكم يجب أن يتكون من ثمانية أرقام';
  END IF;
  IF octet_length(coalesce(p_payload,'{}'::jsonb)::text) > 500000 THEN
    RAISE EXCEPTION 'حجم الطلب أكبر من المسموح';
  END IF;
  INSERT INTO public.teacher_requests(request_kind,requested_name,payload,control_code_hash)
  VALUES ('new_profile',trim(p_requested_name),coalesce(p_payload,'{}'::jsonb),extensions.crypt(p_control_code,extensions.gen_salt('bf',10)))
  RETURNING id INTO request_id;
  RETURN request_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.submit_memorial_application(
  p_full_name text, p_biography text, p_photo_url text DEFAULT NULL,
  p_submitted_by text DEFAULT NULL, p_submitter_contact text DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE request_id bigint;
BEGIN
  IF length(trim(coalesce(p_full_name,''))) NOT BETWEEN 2 AND 200
     OR length(trim(coalesce(p_biography,''))) NOT BETWEEN 10 AND 10000 THEN
    RAISE EXCEPTION 'يرجى إدخال الاسم والنبذة بشكل صحيح';
  END IF;
  IF octet_length(coalesce(p_photo_url,'')) > 500000 THEN
    RAISE EXCEPTION 'حجم الصورة أكبر من المسموح';
  END IF;
  INSERT INTO public.memorial_requests(full_name,biography,photo_url,submitted_by,submitter_contact)
  VALUES (trim(p_full_name),trim(p_biography),p_photo_url,nullif(trim(coalesce(p_submitted_by,'')),''),nullif(trim(coalesce(p_submitter_contact,'')),''))
  RETURNING id INTO request_id;
  RETURN request_id;
END;
$$;

REVOKE ALL ON FUNCTION public.submit_teacher_application(text,jsonb,text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.submit_memorial_application(text,text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_teacher_application(text,jsonb,text) TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.submit_memorial_application(text,text,text,text,text) TO anon, authenticated;

COMMIT;
